INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2563332, 354640, 40679, '<td valign="top">I''ve always loved the idea to photograph a subject like this (upside down in a aquarium) you did great, but I think I''d crop the yellow line at the bottom.</td>', 'I''ve always loved the idea to photograph a subject like this (upside down in a aquarium) you did great, but I think I''d crop the yellow line at the bottom.', '2006-06-28 18:36:08.000000', NULL, 1),
(2563333, 353960, 47274, '<td valign="top">this is amazing</td>', 'this is amazing', '2006-06-28 18:36:25.000000', NULL, 1),
(2563338, 354119, 40679, '<td valign="top">your entry almost looks like a painting or something like that. I love the fact you can see some details (blurry, yes, but there are some!) like the shapes in her body &amp; her lingerie. colors look very nice. great job :)</td>', 'your entry almost looks like a painting or something like that. I love the fact you can see some details (blurry, yes, but there are some!) like the shapes in her body & her lingerie. colors look very nice. great job :)', '2006-06-28 18:38:21.000000', NULL, 1),
(2563340, 354634, 40679, '<td valign="top">pretty cool! I wonder how you''ve created the blue lines in the background. I think the straw in the bulb and the top of the bulb could be a bit lighter, right now the background is too much of an eye-catcher..</td>', 'pretty cool! I wonder how you''ve created the blue lines in the background. I think the straw in the bulb and the top of the bulb could be a bit lighter, right now the background is too much of an eye-catcher..', '2006-06-28 18:38:28.000000', NULL, 1),
