(2566297, 353584, 58469, '<td valign="top">The shapes and colors are intersting.</td>', 'The shapes and colors are intersting.', '2006-06-29 13:44:58.000000', NULL, 1),
(2566298, 353286, 59148, '<td valign="top">Like the idea dno''t like the pieces of glass they just don''t look good wish they were cleaner smoother etc.</td>', 'Like the idea dno''t like the pieces of glass they just don''t look good wish they were cleaner smoother etc.', '2006-06-29 13:45:00.000000', NULL, 1),
(2566299, 353926, 59148, '<td valign="top">Like the composition think the rope takes away from the suject. if not for the suject its a great photo.</td>', 'Like the composition think the rope takes away from the suject. if not for the suject its a great photo.', '2006-06-29 13:45:36.000000', NULL, 1),
(2566301, 354659, 58469, '<td valign="top">I love this picture! The focus on the tree through the glass is done extremely well, you made sure the glass was clean which is awesome. The composition of the tree in its diamond-ish fram and the composition of the entire image is great. Good job.</td>', 'I love this picture! The focus on the tree through the glass is done extremely well, you made sure the glass was clean which is awesome. The composition of the tree in its diamond-ish fram and the composition of the entire image is great. Good job.', '2006-06-29 13:46:08.000000', NULL, 1),
(2566305, 354623, 59148, '<td valign="top">Bubble wrap..lol like the marble hey sell me that marble so I can have a part of your art and if you win I will have an exclusive piece.</td>', 'Bubble wrap..lol like the marble hey sell me that marble so I can have a part of your art and if you win I will have an exclusive piece.', '2006-06-29 13:46:57.000000', NULL, 1),
