INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2567116, 354632, 45475, '<td valign="top">Good symmetry. Nice light and reflection.</td>', 'Good symmetry. Nice light and reflection.', '2006-06-29 18:54:34.000000', NULL, 1),
(2567120, 354584, 45475, '<td valign="top">Lacks contrast or more definition for the darker areas, I think. The idea is great though. Well done.</td>', 'Lacks contrast or more definition for the darker areas, I think. The idea is great though. Well done.', '2006-06-29 18:56:21.000000', NULL, 1),
(2567139, 354393, 57229, '<td valign="top">The lighting is working well for a bauble which itself is ghastly (that''s just my taste or opinion, but it affects my judgement). Between the 2 and the 8 you get a 5 :)</td>', 'The lighting is working well for a bauble which itself is ghastly (that''s just my taste or opinion, but it affects my judgement). Between the 2 and the 8 you get a 5 :)', '2006-06-29 19:01:36.000000', NULL, 1),
(2567142, 354574, 57229, '<td valign="top">My compliments to the bricklayer.</td>', 'My compliments to the bricklayer.', '2006-06-29 19:02:03.000000', NULL, 1),
(2567147, 354537, 57229, '<td valign="top">Nice piece of glass. Might have benefited from being better separated from its background? (Darker background, more complementary colour, maybe the swan raised up on something - just thinking...)</td>', 'Nice piece of glass. Might have benefited from being better separated from its background? (Darker background, more complementary colour, maybe the swan raised up on something - just thinking...)', '2006-06-29 19:04:30.000000', NULL, 1),
(2567149, 354694, 57229, '<td valign="top">Bit chaotic - pretty, though...</td>', 'Bit chaotic - pretty, though...', '2006-06-29 19:05:02.000000', NULL, 1),
(2567155, 354319, 45475, '<td valign="top">Focus is a bit soft but I like the idea and colours.</td>', 'Focus is a bit soft but I like the idea and colours.', '2006-06-29 19:07:27.000000', NULL, 1),
(2567160, 354542, 45475, '<td valign="top">Lovely but lacks contrast...</td>', 'Lovely but lacks contrast...', '2006-06-29 19:09:26.000000', NULL, 1),
(2567166, 354603, 45475, '<td valign="top">Hope you didn''t hurt yourself in the fall!! :P Just kidding, but I do wish the stones were not blurred...</td>', 'Hope you didn''t hurt yourself in the fall!! :P Just kidding, but I do wish the stones were not blurred...', '2006-06-29 19:10:42.000000', NULL, 1),
(2567167, 354291, 57229, '<td valign="top">Very baubley bangley sparkly glassy thingy. Probably the sort of thing that wins.</td>', 'Very baubley bangley sparkly glassy thingy. Probably the sort of thing that wins.', '2006-06-29 19:11:01.000000', NULL, 1),
(2567174, 352830, 45475, '<td valign="top">Nice, but I think the ornaments should have been separated a little more. It looks confusing and unbalanced. There''s also some noise in the image.</td>', 'Nice, but I think the ornaments should have been separated a little more. It looks confusing and unbalanced. There''s also some noise in the image.', '2006-06-29 19:13:31.000000', NULL, 1),
(2567176, 354015, 45475, '<td valign="top">Beautiful building. This could have benefited from a more abstract approach though. Perhaps closer to the windows, with an upward perspective...?</td>', 'Beautiful building. This could have benefited from a more abstract approach though. Perhaps closer to the windows, with an upward perspective...?', '2006-06-29 19:15:03.000000', NULL, 1),
(2567178, 353848, 45475, '<td valign="top">Good colour and light. Well done.</td>', 'Good colour and light. Well done.', '2006-06-29 19:15:35.000000', NULL, 1),
