(2568095, 354689, 59058, '<td valign="top">You found the subject that I''ve been looking for to photograph for this challenge - a broken window glass :) Beautifully captured, colours are looking really nice, and the texture of the woods are really awesome!</td>', 'You found the subject that I''ve been looking for to photograph for this challenge - a broken window glass :) Beautifully captured, colours are looking really nice, and the texture of the woods are really awesome!', '2006-06-30 00:41:11.000000', NULL, 1),
(2568103, 354669, 59058, '<td valign="top">Hah hah, very interesting idea that goes with the challenge title :)</td>', 'Hah hah, very interesting idea that goes with the challenge title :)', '2006-06-30 00:46:15.000000', NULL, 1),
(2568106, 354616, 55199, '<td valign="top">Nice presentation.  Maybe add a little more room at the top of the photo.</td>', 'Nice presentation.  Maybe add a little more room at the top of the photo.', '2006-06-30 00:48:54.000000', NULL, 1),
