(2568121, 354746, 59058, '<td valign="top">I love the eye contact and intense look of the boy. Very captivating :)</td>', 'I love the eye contact and intense look of the boy. Very captivating :)', '2006-06-30 00:52:09.000000', NULL, 1),
(2568126, 354640, 59058, '<td valign="top">Very lovely lighting and colours. Cool idea :)</td>', 'Very lovely lighting and colours. Cool idea :)', '2006-06-30 00:53:21.000000', NULL, 1),
