(2570988, 353439, 30982, '<td valign="top">Interesting subject for the challenge.  A bit on the plain side with it centered, though.</td>', 'Interesting subject for the challenge.  A bit on the plain side with it centered, though.', '2006-06-30 22:58:11.000000', NULL, 1),
(2570989, 354231, 30982, '<td valign="top">Definitely has the "wow" factor going for it.  Lovely colors, wonderful composition.</td>', 'Definitely has the "wow" factor going for it.  Lovely colors, wonderful composition.', '2006-06-30 22:58:48.000000', NULL, 1),
(2570991, 354554, 30982, '<td valign="top">I can see what you were going for (clever title, too) but it''s not clearly enough in focus for my taste.</td>', 'I can see what you were going for (clever title, too) but it''s not clearly enough in focus for my taste.', '2006-06-30 22:59:28.000000', NULL, 1),
(2570994, 353044, 30982, '<td valign="top">Nicely balanced composition.  I like the contrast of the glass color against the sand - not too overbearing, either.</td>', 'Nicely balanced composition.  I like the contrast of the glass color against the sand - not too overbearing, either.', '2006-06-30 23:00:49.000000', NULL, 1),
(2571000, 354393, 30982, '<td valign="top">Good use of lighting but the wicker (?) thing in the back is a bit distracting to me.</td>', 'Good use of lighting but the wicker (?) thing in the back is a bit distracting to me.', '2006-06-30 23:01:51.000000', NULL, 1),
(2571002, 354665, 30982, '<td valign="top">A little on the dark side to see your glass subject.</td>', 'A little on the dark side to see your glass subject.', '2006-06-30 23:02:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2571003, 354119, 30982, '<td valign="top">Good use of glass to create a painting-like photograph!  Well lit, well composed.</td>', 'Good use of glass to create a painting-like photograph!  Well lit, well composed.', '2006-06-30 23:03:08.000000', NULL, 1),
(2571007, 351265, 60731, '<td valign="top">Parts are over exposed in the diamond</td>', 'Parts are over exposed in the diamond', '2006-06-30 23:03:41.000000', NULL, 1),
(2571013, 354420, 60731, '<td valign="top">Love the colors</td>', 'Love the colors', '2006-06-30 23:05:07.000000', NULL, 1),
(2571015, 353260, 30982, '<td valign="top">Maybe just a little too darkly, though I do like how you''ve placed the ball to get that reflection, and how it''s echoed in the rippled water.</td>', 'Maybe just a little too darkly, though I do like how you''ve placed the ball to get that reflection, and how it''s echoed in the rippled water.', '2006-06-30 23:05:14.000000', NULL, 1),
(2571016, 354160, 48616, '<td valign="top">Very nice. Like the lighting, shows the 2 little strands of lint on the left knight. Otherwise great shot.</td>', 'Very nice. Like the lighting, shows the 2 little strands of lint on the left knight. Otherwise great shot.', '2006-06-30 23:05:29.000000', NULL, 1),
(2571018, 353584, 30982, '<td valign="top">Perfectly framed!  Nice, soft coloring as well.</td>', 'Perfectly framed!  Nice, soft coloring as well.', '2006-06-30 23:05:54.000000', NULL, 1),
(2571021, 354160, 30982, '<td valign="top">Needs to be sharper but I like the pose.</td>', 'Needs to be sharper but I like the pose.', '2006-06-30 23:06:46.000000', NULL, 1),
(2571022, 354747, 60731, '<td valign="top">Does not hold my attention</td>', 'Does not hold my attention', '2006-06-30 23:07:13.000000', NULL, 1),
(2571025, 353848, 30982, '<td valign="top">Very interesting reflections in the glass.  The one on the lower left has a charicature (sp?) of a face?</td>', 'Very interesting reflections in the glass.  The one on the lower left has a charicature (sp?) of a face?', '2006-06-30 23:07:34.000000', NULL, 1),
(2571027, 354312, 30982, '<td valign="top">I like the tones used here - might be interesting to see it with the reflection in color and the rest as you have it here.</td>', 'I like the tones used here - might be interesting to see it with the reflection in color and the rest as you have it here.', '2006-06-30 23:08:28.000000', NULL, 1),
(2571028, 354548, 30982, '<td valign="top">I like.  Nice to have a use for that glass apple, huh?</td>', 'I like.  Nice to have a use for that glass apple, huh?', '2006-06-30 23:08:54.000000', NULL, 1),
(2571030, 354009, 30982, '<td valign="top">Colors happen to be my favorites, so there''s an extra point.  Can''t tell what I''m seeing, don''t care.  Very well done.</td>', 'Colors happen to be my favorites, so there''s an extra point.  Can''t tell what I''m seeing, don''t care.  Very well done.', '2006-06-30 23:09:34.000000', NULL, 1),
(2571032, 353881, 30982, '<td valign="top">Seems just a little off-balance - tilted to the right.</td>', 'Seems just a little off-balance - tilted to the right.', '2006-06-30 23:10:42.000000', NULL, 1),
(2571036, 354586, 30982, '<td valign="top">Good low key shot.</td>', 'Good low key shot.', '2006-06-30 23:11:21.000000', NULL, 1),
(2571037, 354631, 30982, '<td valign="top">Headlight as abstract - works pretty well.</td>', 'Headlight as abstract - works pretty well.', '2006-06-30 23:11:50.000000', NULL, 1),
(2571040, 354408, 30982, '<td valign="top">That''s all glass?  How did it get there?  Nice composition - like the reflection and the touch of orange from the flowers in the background.  Could use just a bit more contrast, I think.</td>', 'That''s all glass?  How did it get there?  Nice composition - like the reflection and the touch of orange from the flowers in the background.  Could use just a bit more contrast, I think.', '2006-06-30 23:12:57.000000', NULL, 1),
(2571042, 354640, 30982, '<td valign="top">Interesting!  Color tones work well, even if the fingers seem a bit dark.  Looks like something Scalvert would think up.</td>', 'Interesting!  Color tones work well, even if the fingers seem a bit dark.  Looks like something Scalvert would think up.', '2006-06-30 23:13:41.000000', NULL, 1),
(2571045, 354015, 60731, '<td valign="top">Too common</td>', 'Too common', '2006-06-30 23:14:03.000000', NULL, 1),
(2571046, 352289, 30982, '<td valign="top">Heh!  Works.  Made me smile.</td>', 'Heh!  Works.  Made me smile.', '2006-06-30 23:14:04.000000', NULL, 1),
(2571048, 354319, 30982, '<td valign="top">Definitely lots of facets - in fact maybe too many.  Seems a bit busy and cluttered.</td>', 'Definitely lots of facets - in fact maybe too many.  Seems a bit busy and cluttered.', '2006-06-30 23:14:59.000000', NULL, 1),
(2571050, 354075, 30982, '<td valign="top">Neat!  Better be a live bug.</td>', 'Neat!  Better be a live bug.', '2006-06-30 23:15:22.000000', NULL, 1),
(2571054, 354584, 30982, '<td valign="top">Kinda looks like a candle holder.  The center bright spot dominates, though.</td>', 'Kinda looks like a candle holder.  The center bright spot dominates, though.', '2006-06-30 23:16:29.000000', NULL, 1),
(2571055, 351920, 30982, '<td valign="top">I''ll take your word for it that it''s glass, but hard to tell from the picture itself.</td>', 'I''ll take your word for it that it''s glass, but hard to tell from the picture itself.', '2006-06-30 23:16:55.000000', NULL, 1),
(2571056, 353250, 30982, '<td valign="top">The shadows hurt you a little here.  I like the idea, and I like the blinds in the mirror.  She doesn''t look particularly passionate, though.</td>', 'The shadows hurt you a little here.  I like the idea, and I like the blinds in the mirror.  She doesn''t look particularly passionate, though.', '2006-06-30 23:17:42.000000', NULL, 1),
(2571057, 354089, 60731, '<td valign="top">Would have looked better if the white was not over exposed</td>', 'Would have looked better if the white was not over exposed', '2006-06-30 23:18:02.000000', NULL, 1),
(2571061, 354610, 30982, '<td valign="top">The background item on the right and the light-colored objects behind detract from your subject, which while interesting, might be even more interesting if photographed from the front.  I can also see where the paper you put under it ends - may need to get a bigger "backdrop" or shoot from a different angle.</td>', 'The background item on the right and the light-colored objects behind detract from your subject, which while interesting, might be even more interesting if photographed from the front.  I can also see where the paper you put under it ends - may need to get a bigger "backdrop" or shoot from a different angle.', '2006-06-30 23:19:33.000000', NULL, 1),
(2571063, 351265, 30982, '<td valign="top">Great angle, DOF, but needs just a touch more clarity on the non-diamond.</td>', 'Great angle, DOF, but needs just a touch more clarity on the non-diamond.', '2006-06-30 23:20:15.000000', NULL, 1),
(2571065, 354311, 30982, '<td valign="top">Sweet abstract with great color and light.</td>', 'Sweet abstract with great color and light.', '2006-06-30 23:20:53.000000', NULL, 1),
(2571067, 353286, 30982, '<td valign="top">Big glass somethings?  Colors are good but my eye just sort of wanders without finding something to settle on.</td>', 'Big glass somethings?  Colors are good but my eye just sort of wanders without finding something to settle on.', '2006-06-30 23:21:43.000000', NULL, 1),
(2571068, 354718, 30982, '<td valign="top">Good execution of a classic approach.</td>', 'Good execution of a classic approach.', '2006-06-30 23:21:59.000000', NULL, 1),
(2571070, 354073, 30982, '<td valign="top">Never seen cow eggs before.  Lighting is a bit flat, but subjects are definitely unique.</td>', 'Never seen cow eggs before.  Lighting is a bit flat, but subjects are definitely unique.', '2006-06-30 23:22:28.000000', NULL, 1),
(2571071, 354504, 30982, '<td valign="top">A bit disturbing if this is a frog encased in glass?  Seems out of focus to me throughout.</td>', 'A bit disturbing if this is a frog encased in glass?  Seems out of focus to me throughout.', '2006-06-30 23:23:30.000000', NULL, 1),
(2571074, 354617, 30982, '<td valign="top">Ah, the kit lens?   Specs on the lens seem to draw unwanted attention, but I like the colors in the reflection.</td>', 'Ah, the kit lens?   Specs on the lens seem to draw unwanted attention, but I like the colors in the reflection.', '2006-06-30 23:24:29.000000', NULL, 1),
(2571078, 352406, 30982, '<td valign="top">Very nice "set up" of a glass figurine!  Would make a nice cover of a children''s book.</td>', 'Very nice "set up" of a glass figurine!  Would make a nice cover of a children''s book.', '2006-06-30 23:25:17.000000', NULL, 1),
(2571082, 354437, 30982, '<td valign="top">It kinda looks like the base doesn''t belong with the figurine.  The hot spot on the base and the secondary shadow detract.</td>', 'It kinda looks like the base doesn''t belong with the figurine.  The hot spot on the base and the secondary shadow detract.', '2006-06-30 23:27:14.000000', NULL, 1),
(2571085, 354689, 30982, '<td valign="top">Good find, well seen, well captured.</td>', 'Good find, well seen, well captured.', '2006-06-30 23:27:33.000000', NULL, 1),
(2571087, 354277, 30982, '<td valign="top">It''s hard to really photograph these things well without using those nifty light base things.  In my opinion, this isn''t a good background for the subject.</td>', 'It''s hard to really photograph these things well without using those nifty light base things.  In my opinion, this isn''t a good background for the subject.', '2006-06-30 23:29:02.000000', NULL, 1),
(2571092, 354297, 30982, '<td valign="top">Almost looks like it''s melting into the mirror below.  It''s not quite centered - either needs to be completely, or needs more room on one side; since it doesn''t appear to be perfectly round, give it more room on one side.</td>', 'Almost looks like it''s melting into the mirror below.  It''s not quite centered - either needs to be completely, or needs more room on one side; since it doesn''t appear to be perfectly round, give it more room on one side.', '2006-06-30 23:30:38.000000', NULL, 1),
(2571110, 353873, 30982, '<td valign="top">Intriguing effect!</td>', 'Intriguing effect!', '2006-06-30 23:42:08.000000', NULL, 1),
(2571137, 354111, 60779, '<td valign="top">I think the street lights are the focus, instead of the glass on the parking garage. They are too dominant in the photo.</td>', 'I think the street lights are the focus, instead of the glass on the parking garage. They are too dominant in the photo.', '2006-06-30 23:53:39.000000', NULL, 1),
(2571142, 354734, 60779, '<td valign="top">Nice comp and sky colors</td>', 'Nice comp and sky colors', '2006-06-30 23:54:33.000000', NULL, 1),
(2571148, 354480, 60779, '<td valign="top">I like the abstract nature of the reflection. Good photo.</td>', 'I like the abstract nature of the reflection. Good photo.', '2006-06-30 23:55:38.000000', NULL, 1),
(2571151, 354669, 60779, '<td valign="top">I would have enjoyed it more with a more contrasting background.</td>', 'I would have enjoyed it more with a more contrasting background.', '2006-06-30 23:56:11.000000', NULL, 1),
(2571157, 354618, 60779, '<td valign="top">Well taken, focused, balanced. The subject isn''t that interesting for me, but that doesn''t take away from the score of the picture.</td>', 'Well taken, focused, balanced. The subject isn''t that interesting for me, but that doesn''t take away from the score of the picture.', '2006-06-30 23:57:31.000000', NULL, 1),
(2571159, 353158, 61357, '<td valign="top">This is absolutely stunning.  Great composition, and lighting. I rate this #10</td>', 'This is absolutely stunning.  Great composition, and lighting. I rate this #10', '2006-06-30 23:58:23.000000', NULL, 1),
(2571162, 354633, 60779, '<td valign="top">I like the focus and the contrast on the edge of the glass pieces.</td>', 'I like the focus and the contrast on the edge of the glass pieces.', '2006-06-30 23:59:06.000000', NULL, 1),
(2571168, 354126, 33560, '<td valign="top">Extraordinary, nicely observed, nicely framed.  I fear the invisibility of the glass in the photo will cost a lot in terms of points, but I like the result</td>', 'Extraordinary, nicely observed, nicely framed.  I fear the invisibility of the glass in the photo will cost a lot in terms of points, but I like the result', '2006-07-01 00:02:04.000000', NULL, 1),
(2571180, 354554, 60779, '<td valign="top">I feel an uncomfortable sense of motion.</td>', 'I feel an uncomfortable sense of motion.', '2006-07-01 00:05:23.000000', NULL, 1),
(2571182, 354358, 33560, '<td valign="top">Great choice to present in B&amp;W. Very nice.</td>', 'Great choice to present in B&W. Very nice.', '2006-07-01 00:06:08.000000', NULL, 1),
(2571201, 354535, 33560, '<td valign="top">It''s a picture of a bloomin'' lightbulb in the garden - which I think is different. Placement is a bit awkward with the lamp being right at the edge of the hostas.  Static central placement, blown highlights on the right, and uninteresting foreground hurt the photo.  So does small subject size. Still, it''s funny: thanks for the effort.</td>', 'It''s a picture of a bloomin'' lightbulb in the garden - which I think is different. Placement is a bit awkward with the lamp being right at the edge of the hostas.  Static central placement, blown highlights on the right, and uninteresting foreground hurt the photo.  So does small subject size. Still, it''s funny: thanks for the effort.', '2006-07-01 00:12:14.000000', NULL, 1),
(2571208, 353268, 30982, '<td valign="top">A bit blown on the lower right side which kinda draws attention away a little, but a very interesting approach to the challenge!</td>', 'A bit blown on the lower right side which kinda draws attention away a little, but a very interesting approach to the challenge!', '2006-07-01 00:13:27.000000', NULL, 1),
(2571211, 353030, 30982, '<td valign="top">Good shot, nicely balanced - I must be stuck in the other challenge because I''m also compelled to say "nice bokeh" - which it is.</td>', 'Good shot, nicely balanced - I must be stuck in the other challenge because I''m also compelled to say "nice bokeh" - which it is.', '2006-07-01 00:14:12.000000', NULL, 1),
(2571213, 353926, 30982, '<td valign="top">These make good subjects - I like the textures.</td>', 'These make good subjects - I like the textures.', '2006-07-01 00:14:46.000000', NULL, 1),
(2571220, 353960, 30982, '<td valign="top">Somehow the bottle looks oddly out of proportion with the image, but the colors are good - like the darkness of it.</td>', 'Somehow the bottle looks oddly out of proportion with the image, but the colors are good - like the darkness of it.', '2006-07-01 00:15:28.000000', NULL, 1),
(2571223, 354084, 30982, '<td valign="top">Pretty nice abstract but I''m not fond of the big dark part on the right side.</td>', 'Pretty nice abstract but I''m not fond of the big dark part on the right side.', '2006-07-01 00:16:12.000000', NULL, 1),
(2571224, 354546, 33560, '<td valign="top">Super! very nicely observed.  Rare, unexpected.</td>', 'Super! very nicely observed.  Rare, unexpected.', '2006-07-01 00:16:15.000000', NULL, 1),
(2571226, 354271, 30982, '<td valign="top">Well seen, beautifully exposed/captured.</td>', 'Well seen, beautifully exposed/captured.', '2006-07-01 00:16:43.000000', NULL, 1),
(2571229, 354449, 30982, '<td valign="top">An interesting composition - I like the light coming from the right and highlighting that edge.  I think I may prefer a less-textured backing, though.</td>', 'An interesting composition - I like the light coming from the right and highlighting that edge.  I think I may prefer a less-textured backing, though.', '2006-07-01 00:17:56.000000', NULL, 1),
(2571237, 354746, 33560, '<td valign="top">Somehow the graininess works to strengthen the pensive mood set by the model and the high key treatment of him.  It''s a great shot!.</td>', 'Somehow the graininess works to strengthen the pensive mood set by the model and the high key treatment of him.  It''s a great shot!.', '2006-07-01 00:21:17.000000', NULL, 1),
(2571240, 354604, 30982, '<td valign="top">That''s really quite lovely.  Nice choice of setting.</td>', 'That''s really quite lovely.  Nice choice of setting.', '2006-07-01 00:22:57.000000', NULL, 1),
(2571243, 354420, 30982, '<td valign="top">Nice, clean, simple.  Well done.</td>', 'Nice, clean, simple.  Well done.', '2006-07-01 00:23:32.000000', NULL, 1),
(2571246, 354742, 30982, '<td valign="top">Love this.  Best of show for meeting challenge topic!</td>', 'Love this.  Best of show for meeting challenge topic!', '2006-07-01 00:24:05.000000', NULL, 1),
(2571247, 351603, 30982, '<td valign="top">Very pretty!  Need to take full advantage of the 640 pixels you''re allowed on the longest side so your picture can be seen more clearly!</td>', 'Very pretty!  Need to take full advantage of the 640 pixels you''re allowed on the longest side so your picture can be seen more clearly!', '2006-07-01 00:24:52.000000', NULL, 1),
(2571252, 354590, 30982, '<td valign="top">Well it''s different!  Like the lighting.  Almost looks like a wee bit of camera shake or model movement hear the forehead and eye.</td>', 'Well it''s different!  Like the lighting.  Almost looks like a wee bit of camera shake or model movement hear the forehead and eye.', '2006-07-01 00:26:32.000000', NULL, 1),
(2571254, 354221, 30982, '<td valign="top">I''ve seen a couple that would make good stock pictures - this is another one of those.</td>', 'I''ve seen a couple that would make good stock pictures - this is another one of those.', '2006-07-01 00:26:59.000000', NULL, 1),
(2571256, 354591, 30982, '<td valign="top">Vivid and colorful!</td>', 'Vivid and colorful!', '2006-07-01 00:27:37.000000', NULL, 1),
(2571260, 352772, 30982, '<td valign="top">You''ve got to step away from the computer.... Different take - I do like the single red reflection, too.</td>', 'You''ve got to step away from the computer.... Different take - I do like the single red reflection, too.', '2006-07-01 00:28:25.000000', NULL, 1),
(2571289, 354621, 61357, '<td valign="top">Creative, nice reflection interesting composition in the reflection, too.</td>', 'Creative, nice reflection interesting composition in the reflection, too.', '2006-07-01 00:38:24.000000', NULL, 1),
(2571294, 354591, 61357, '<td valign="top">Nice color and repetion.</td>', 'Nice color and repetion.', '2006-07-01 00:40:39.000000', NULL, 1),
(2571298, 354291, 61357, '<td valign="top">Interesting, I like all the diffrent colors.</td>', 'Interesting, I like all the diffrent colors.', '2006-07-01 00:41:30.000000', NULL, 1),
(2571313, 352295, 61357, '<td valign="top">I like this composition and the dark and light color tones cast against one another.</td>', 'I like this composition and the dark and light color tones cast against one another.', '2006-07-01 00:46:38.000000', NULL, 1),
(2571325, 354586, 61357, '<td valign="top">Love the subtle color tone in this.</td>', 'Love the subtle color tone in this.', '2006-07-01 00:51:35.000000', NULL, 1),
(2571332, 354689, 61357, '<td valign="top">I love this, it is such a simple composition!</td>', 'I love this, it is such a simple composition!', '2006-07-01 00:53:11.000000', NULL, 1),
(2571342, 353926, 61357, '<td valign="top">I really like the blue in this Might have made it just a bit more interesting to place it against a yellow or orange background, just for pop...it is beautiful anyway!</td>', 'I really like the blue in this Might have made it just a bit more interesting to place it against a yellow or orange background, just for pop...it is beautiful anyway!', '2006-07-01 00:55:08.000000', NULL, 1),
(2571355, 354231, 61357, '<td valign="top">Really beautiful composition.  Had to click on the larger image to really see whet you had done.  Gorgeous!</td>', 'Really beautiful composition.  Had to click on the larger image to really see whet you had done.  Gorgeous!', '2006-07-01 00:57:53.000000', NULL, 1),
(2571359, 354075, 41047, '<td valign="top">one of my favorites in this challenge. i liked the colors a lot.</td>', 'one of my favorites in this challenge. i liked the colors a lot.', '2006-07-01 00:58:12.000000', NULL, 1),
(2571385, 354630, 59629, '<td valign="top">Out of all the eyeglasses and words images this one is by far the best... very creative... I really like this one!!!</td>', 'Out of all the eyeglasses and words images this one is by far the best... very creative... I really like this one!!!', '2006-07-01 01:06:45.000000', NULL, 1),
