(2572882, 353250, 56673, '<td valign="top">Great concept.  But she looks more anxious than passionate.</td>', 'Great concept.  But she looks more anxious than passionate.', '2006-07-01 18:53:17.000000', NULL, 1),
(2572884, 352289, 35274, '<td valign="top">That''s pretty cool!</td>', 'That''s pretty cool!', '2006-07-01 18:54:29.000000', NULL, 1),
