(2573349, 353207, 30982, '<td valign="top">I don''t think I want to know why someone has a colection of glass vegetables and fruit... Colorful and crisp.</td>', 'I don''t think I want to know why someone has a colection of glass vegetables and fruit... Colorful and crisp.', '2006-07-01 22:07:58.000000', NULL, 1),
(2573351, 353398, 30982, '<td valign="top">Very nice way to integrate glass into an excellent picture!</td>', 'Very nice way to integrate glass into an excellent picture!', '2006-07-01 22:08:19.000000', NULL, 1),
(2573352, 354614, 30982, '<td valign="top">Wow - very well lit!  Nicely done for a glass figurine.</td>', 'Wow - very well lit!  Nicely done for a glass figurine.', '2006-07-01 22:08:38.000000', NULL, 1),
(2573353, 354067, 30982, '<td valign="top">Clever - painting with light?</td>', 'Clever - painting with light?', '2006-07-01 22:09:09.000000', NULL, 1),
