(2573425, 354693, 30982, '<td valign="top">Very nice subject choice for the challenge - well captured.</td>', 'Very nice subject choice for the challenge - well captured.', '2006-07-01 22:48:42.000000', NULL, 1),
(2573426, 352312, 30982, '<td valign="top">Rather plain.  The glass just looks like a blue blob thrown there for the sake of a picture.</td>', 'Rather plain.  The glass just looks like a blue blob thrown there for the sake of a picture.', '2006-07-01 22:49:36.000000', NULL, 1),
(2573427, 354289, 30982, '<td valign="top">Striking.  Like the lighting on the face, particularly the eye.  Well cropped, too.</td>', 'Striking.  Like the lighting on the face, particularly the eye.  Well cropped, too.', '2006-07-01 22:50:14.000000', NULL, 1),
(2573430, 353485, 30982, '<td valign="top">Lovely reflection shot - the window slant seems kinda neat in this context.</td>', 'Lovely reflection shot - the window slant seems kinda neat in this context.', '2006-07-01 22:51:04.000000', NULL, 1),
(2573431, 354209, 30982, '<td valign="top">I like this as an abstract - texture is interesting!</td>', 'I like this as an abstract - texture is interesting!', '2006-07-01 22:51:26.000000', NULL, 1),
